import java.text.Normalizer;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * A filter over the customer list, as the backend understands it.
 *
 * <p>Two independent parts, combined with AND:
 * <ul>
 * <li>a free-text {@code name} filter, split on whitespace into terms, every one
 * of which must occur in the first or the last name, ignoring case and
 * accents;</li>
 * <li>a set of {@code statuses}; empty means "any status".</li>
 * </ul>
 *
 * <p>An {@link #EMPTY} filter matches every customer.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** Matches everything. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name.trim();
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /** True when this filter constrains nothing. */
    public boolean isEmpty() {
        return name.isEmpty() && statuses.isEmpty();
    }

    /**
     * The name filter as normalised search terms; empty when no name was
     * entered. Leading, trailing and repeated whitespace is not significant.
     */
    public List<String> nameTerms() {
        return name.isEmpty() ? List.of() : List.of(WHITESPACE.split(normalize(name)));
    }

    /** True when {@code customer} satisfies both parts of this filter. */
    public boolean matches(Customer customer) {
        return asPredicate().test(customer);
    }

    /**
     * This filter as a predicate, with the search terms normalised once up front
     * rather than once per candidate row.
     */
    public Predicate<Customer> asPredicate() {
        List<String> terms = nameTerms();
        Set<CustomerStatus> wanted = statuses;
        return customer -> {
            if (!wanted.isEmpty() && !wanted.contains(customer.status())) {
                return false;
            }
            if (terms.isEmpty()) {
                return true;
            }
            String firstName = normalize(customer.firstName());
            String lastName = normalize(customer.lastName());
            for (String term : terms) {
                if (!firstName.contains(term) && !lastName.contains(term)) {
                    return false;
                }
            }
            return true;
        };
    }

    /**
     * Folds a string down to what matching compares: lower case, with accents
     * removed, so that {@code makinen}, {@code MAKINEN} and {@code mäkinen} all
     * come out as {@code makinen}.
     */
    public static String normalize(String text) {
        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
