+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+        assertEquals("Aaltonen", test(grid()).getCellText(0, 1));
+
+        setName("aal ada");
+        assertEquals(2, gridSize(), "term order must not matter");
+
+        setName("ada virtanen");
+        assertEquals(0, gridSize());
+        assertEquals("Showing 0 of 500", summaryText());
+    }
